import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.2cFhd8Ux.js";const g=JSON.parse('{"title":"Week 11 — Building LLM Features","description":"","frontmatter":{"source":"weeks/11-llm-features/README.md"},"headers":[],"relativePath":"weeks/11-llm-features/index.md","filePath":"weeks/11-llm-features/index.md"}'),s={name:"weeks/11-llm-features/index.md"};function n(i,e,l,d,h,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="week-11--building-llm-features" tabindex="-1">Week 11 — Building LLM Features <a class="header-anchor" href="#week-11--building-llm-features" aria-label="Permalink to &quot;Week 11 — Building LLM Features&quot;">​</a></h1><blockquote><p>An LLM feature is a parser with a probabilistic front end: the model only proposes, and your schema, validation, retries and budget decide what the rest of the system accepts.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before the Seminar</strong></td><td>The reading and your reading response · submit the week 10 security review (the Seminar opens with its quiz) · check that your free API key works, or that you can reach the lab machine (<a href="./../../setup/api-keys.html">setup</a>)</td></tr><tr><td><strong>Seminar</strong></td><td>Due-date quiz · talk: structured outputs, tool calling, retries and repair, failure handling, cost and latency budgets, retrieval basics (<a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/slides/week-11.html" target="_blank" rel="noreferrer">slides</a>) · debate: does constraining the format hurt reasoning? · demo: one request, a retry, the cost log · Lab preview</td></tr><tr><td><strong>Lab</strong></td><td><a href="./lab.html#lab--a-validated-extractor-replay-read-run-live-75-min">The <code>eval-harness</code> kit</a>: replay 30 recorded cases, read the schema and the retry loop, run the feature live, record your own baseline. <strong>Checkoff:</strong> one live recorded run with its cost and latency log</td></tr><tr><td><strong>Due before next week&#39;s Seminar</strong></td><td>Default 11:59 pm the night before: the <a href="./lab.html#assignment--one-measured-improvement-and-an-error-analysis">assignment</a>, one improvement measured against your baseline plus an error analysis of the 30 cases</td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: code changes, analysis scripts · 🟡 AI limited: the error analysis (you read and code every failure; an AI may help tabulate, logged) · 🔴 AI off: reading the schema and retry loop (Lab Part 2), the quiz, the reading response</td></tr><tr><td><strong>Reading</strong></td><td>Tam et al., &quot;Let Me Speak Freely?&quot;, with .txt&#39;s reply (<a href="#reading">below</a>)</td></tr><tr><td><strong>Reading response</strong></td><td>150–250 words, 🔴 AI off, on Canvas, before the Seminar (<a href="#reading">prompt</a>)</td></tr><tr><td><strong>Team project</strong></td><td>The PR round closed before this Seminar; M2 is due before the week 13 Seminar (<a href="./../../project/milestones.html#m2-major-contribution">milestones</a>). If your contribution calls an LLM, start <code>course/EVAL_PLAN.md</code> (<a href="./../../templates/EVAL_PLAN.html">template</a>)</td></tr><tr><td><strong>Graduate track</strong></td><td><strong>Interim results</strong> due before the week 12 Seminar (<a href="./../../graduate/empirical-study.html#interim-results-10-points-15">empirical study</a>). No seminar paper is set this week</td></tr><tr><td><strong>Time</strong></td><td>Meetings 2.5 h · outside about 6 h (CS [5xxx]: about 7.5 h)</td></tr></tbody></table><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>The data rule applies to every live call.</strong> Free tiers may train on what you send (<a href="./../../TOOLS.html#the-data-rule">Tool Handout: The data rule</a>). Send only the kit&#39;s cases and requests you made up. Recordings store everything you sent and get committed, so never type personal data into <code>npm run extract</code>.</p></div><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li>Distinguish asking for JSON, a provider&#39;s JSON mode and schema-constrained <a href="./../../resources/glossary.html#structured-output">structured output</a>, and explain why you validate in code in every case.</li><li>Read a schema written as data and its validator, and say what validation catches (form) and misses (meaning).</li><li>Design a retry with repair, and name the risk that a retry satisfies the validator by inventing data.</li><li>Log and budget tokens, cost and latency per request, including what retries add.</li><li>Measure one change against a baseline on the same cases and model, case by case, and write an error analysis with categories, counts and examples.</li></ol><h2 id="seminar" tabindex="-1">Seminar <a class="header-anchor" href="#seminar" aria-label="Permalink to &quot;Seminar&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Block</th><th>Minutes</th><th>What happens</th></tr></thead><tbody><tr><td>Due-date quiz</td><td>7</td><td>On your week 10 security review, 🔴 AI off (<a href="./../../assessment/quizzes.html">quizzes</a>)</td></tr><tr><td>Concept talk</td><td>25</td><td>The feature as a pipeline; structured outputs; <a href="./../../resources/glossary.html#tool-call">tool calling</a>; retries and repair; failure handling; budgets; retrieval (<a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/slides/week-11.html" target="_blank" rel="noreferrer">slides</a>)</td></tr><tr><td>Debate</td><td>20</td><td>Tam et al. against .txt: each half of the room argues one side from the papers, then the room designs the experiment that would settle it for our extractor</td></tr><tr><td>Live demo</td><td>10</td><td>One request live; a reply that fails validation and the retry that follows; the request in the recording; its line in <code>calls.jsonl</code></td></tr><tr><td>Lab preview</td><td>5</td><td>Your key or the lab machine; your own recordings folder; the checkoff</td></tr></tbody></table><h2 id="lab" tabindex="-1">Lab <a class="header-anchor" href="#lab" aria-label="Permalink to &quot;Lab&quot;">​</a></h2><p>The <a href="./lab.html">lab</a> uses the <a href="https://github.com/Boyu-Zhang-UOI/eswa-eval-harness" target="_blank" rel="noreferrer"><code>eval-harness</code> kit</a>: an extractor that turns &quot;Book a room for 12 people next Tuesday 2–3pm with a projector&quot; into a booking object for <code>roomly</code>, validated in code, with up to three attempts. You replay the 30 shipped cases (hand-written recordings: about 97% valid, about 63% fully correct), read the validator and the retry loop, then record a live baseline into your own folder, leaving the shipped recordings untouched.</p><h2 id="reading" tabindex="-1">Reading <a class="header-anchor" href="#reading" aria-label="Permalink to &quot;Reading&quot;">​</a></h2><p><strong>Tam et al., <a href="https://aclanthology.org/2024.emnlp-industry.91/" target="_blank" rel="noreferrer">&quot;Let Me Speak Freely? A Study on the Impact of Format Restrictions on Performance of Large Language Models&quot;</a></strong> (EMNLP 2024 Industry), read with <strong>.txt&#39;s reply, <a href="https://blog.dottxt.ai/say-what-you-mean.html" target="_blank" rel="noreferrer">&quot;Say What You Mean&quot;</a></strong>, the reading list&#39;s <a href="./../../resources/reading-list.html#week-11--building-llm-features">core pick</a>. Tam et al. report that reasoning gets worse when the output format is restricted. .txt traces the effect to prompts that differed between conditions and to an LLM used as the answer parser; with matched prompts, structured output did as well or better (GSM8K 0.77 → 0.78, Last Letter 0.73 → 0.77). Compare the two methods sections.</p><p><strong>Reading response prompt</strong> (150–250 words, 🔴 AI off, on Canvas): State each side&#39;s claim in one sentence. Name the one difference in method that you think explains most of the disagreement, and say whether it is a difference in the treatment or in the measurement. Then decide what it means for this week&#39;s extractor, which asks for plain JSON in the prompt and validates it in code: would you switch on a provider&#39;s structured-output mode, and what would you measure to know? End with one question for the debate.</p><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><ul><li><strong>The model proposes; code disposes.</strong> A reply is untrusted input: parse it, validate it, and let roomly still enforce its booking rules.</li><li><strong>Valid is not correct.</strong> A schema checks types, enums and patterns. It can&#39;t tell that &quot;next Tuesday&quot; became the wrong week. Report validity and correctness separately.</li><li><strong>Constrained decoding guarantees form, not meaning.</strong> Vendors report 100% schema adherence with it (<a href="https://openai.com/index/introducing-structured-outputs-in-the-api/" target="_blank" rel="noreferrer">OpenAI</a>); whether it costs quality depends on how you measure, as the debate shows. Validate anyway.</li><li><strong>A retry is a second, longer prompt.</strong> Feed back the exact errors, cap the attempts, decide what happens after the last one (fail closed, or ask), and watch for a model that passes the validator by inventing data.</li><li><strong>Tool calling is structured output with a dispatcher.</strong> Tool-calling agents succeeded on under 50% of τ-bench tasks, and pass^8 was below 25% in retail: reliability (<a href="./../../resources/glossary.html#passk-and-passk">pass^k</a>) is its own metric (<a href="https://arxiv.org/abs/2406.12045" target="_blank" rel="noreferrer">Yao et al.</a>).</li><li><strong>Budgets are per request, and retries multiply them.</strong> Log every attempt, read p95 as well as the median, and take prices from TOOLS.md, never from code.</li><li><strong>Retrieval has its own failure points,</strong> and RAG &quot;can only be fully validated in operation&quot; (<a href="https://arxiv.org/abs/2401.05856" target="_blank" rel="noreferrer">Barnett et al.</a>, <a href="./../../resources/glossary.html#retrieval-augmented-generation-rag">RAG</a>). For bookings, the room catalog belongs in a query to roomly, not in the prompt.</li><li><strong>A recording describes only the prompt that produced it.</strong> The kit keys <a href="./../../resources/glossary.html#recorded-responses">recorded responses</a> by a hash of the exact request: change the prompt and every replay fails until you record again.</li></ul><h2 id="check-your-understanding" tabindex="-1">Check your understanding <a class="header-anchor" href="#check-your-understanding" aria-label="Permalink to &quot;Check your understanding&quot;">​</a></h2><ol><li>The shipped run is about 97% valid but about 63% fully correct. Where does the other third go, and which of those failures could any schema catch?</li><li>You add a cross-field rule to <code>schema.js</code>. Why might replay now fail on some cases but not others?</li><li>Why does a retry cost more tokens than the first attempt, although it asks for the same object?</li><li>Your change fixes 3 cases and breaks 1, out of 30, in one run. What can you claim?</li></ol><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><ul><li><strong>Rate-limited or down:</strong> switch provider in <code>.env</code> (Groq, OpenRouter or the lab machine; <a href="./../../TOOLS.html#llm-apis-for-the-kits">Tool Handout: LLM APIs for the kits</a>), log it, and record into a new folder: a different model is a different baseline. Raise <code>--delay-ms</code> on a tight limit.</li><li><strong>The lab machine&#39;s queue is long:</strong> record ten cases with <code>--only</code> for the checkoff and the rest later (<a href="./../../resources/troubleshooting.html#the-lab-machine-is-slow-or-unreachable">troubleshooting</a>).</li><li><strong>No live model at all:</strong> Parts 1 and 2 replay offline. Analyze the shipped recordings, say they are hand-written, and record your baseline when a provider is back. API errors: <a href="./../../resources/troubleshooting.html#my-api-call-fails-401-404-429">troubleshooting</a>.</li></ul><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>Barnett et al., <a href="https://arxiv.org/abs/2401.05856" target="_blank" rel="noreferrer">&quot;Seven Failure Points When Engineering a RAG System&quot;</a>, with Es et al., <a href="https://arxiv.org/abs/2309.15217" target="_blank" rel="noreferrer">&quot;Ragas&quot;</a>, whose metrics are themselves LLM judges (next week&#39;s topic).</li><li>Hong, Troynikov &amp; Huber, <a href="https://www.trychroma.com/research/context-rot" target="_blank" rel="noreferrer">&quot;Context Rot&quot;</a>: a focused prompt of about 300 tokens beat the full 113K-token one.</li><li>CS [5xxx]: Tam et al. vs .txt is on the <a href="./../../resources/reading-list.html#replicable-studies">replicable list</a>.</li><li>Previous week: <a href="./../10-supply-chain/">Supply Chain and Secure Code</a>. Next week: <a href="./../12-evals/">Evals</a>.</li></ul>',23)])])}const m=t(s,[["render",n]]);export{g as __pageData,m as default};
